class DashboardPage {

    // --- Assertions ---

    verifyDashboardIsDisplayed() {
        cy.url().should('contain', '/dashboard');
        cy.contains('h6', 'Dashboard').should('be.visible');
        return this;
    }

    verifyWidgetsAreVisible() {
        // Verify the user dropdown trigger is rendered — confirms the app shell loaded.
        // Previous assertion (.oxd-glass-button + 'U') was user-initial-dependent;
        // this check is neutral and works for any account.
        cy.get('[class*="userdropdown-tab"]').should('be.visible');
        return this;
    }
}

export default new DashboardPage();
